CREATE TABLE campeonatos (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(150),identidade_id INT UNSIGNED NULL,tipo VARCHAR(30),formato VARCHAR(30),data_inicio DATE NULL,status VARCHAR(30) DEFAULT 'ativo',ativo INT DEFAULT 1,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE participantes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(100),time_nome VARCHAR(100),sigla VARCHAR(10),escudo_url TEXT,ativo INT DEFAULT 1,participacoes_futuras INT DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE titulos (id INT AUTO_INCREMENT PRIMARY KEY,campeonato_id INT NULL,titulo VARCHAR(150),descricao TEXT,imagem_base64 TEXT) ENGINE=InnoDB;
CREATE TABLE artilharia (id INT AUTO_INCREMENT PRIMARY KEY,campeonato_id INT,gols INT) ENGINE=InnoDB;
CREATE TABLE partidas (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campeonato_id INT,rodada INT,turno INT,mandante_id INT,visitante_id INT,gols_mandante INT NULL,gols_visitante INT NULL,data_partida DATETIME,status VARCHAR(30),comprovacao_url TEXT,ativo INT DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE jogos_mata_mata (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campeonato_id INT,fase VARCHAR(30),ordem INT,jogo INT,time_a_id INT NULL,time_b_id INT NULL,origem_a_fase VARCHAR(30) NULL,origem_a_ordem INT NULL,origem_a_tipo VARCHAR(30) DEFAULT 'vencedor',origem_b_fase VARCHAR(30) NULL,origem_b_ordem INT NULL,origem_b_tipo VARCHAR(30) DEFAULT 'vencedor',gols_a INT NULL,gols_b INT NULL,penaltis_a INT NULL,penaltis_b INT NULL,vencedor_id INT NULL,status VARCHAR(30),ativo INT DEFAULT 1) ENGINE=InnoDB;
